global M00: Field = 0x109b7f411ba0e4c9b2b70caf5c36a7b194be7c11ad24378bfedb68592ba8118b;
global M01: Field = 0x2969f27eed31a480b9c36c764379dbca2cc8fdd1415c3dded62940bcde0bd771;
global M02: Field = 0x143021ec686a3f330d5f9e654638065ce6cd79e28c5b3753326244ee65a1b1a7;
global M10: Field = 0x16ed41e13bb9c0c66ae119424fddbcbc9314dc9fdbdeea55d6c64543dc4903e0;
global M11: Field = 0x2e2419f9ec02ec394c9871c832963dc1b89d743c8c7b964029b2311687b1fe23;
global M12: Field = 0x176cc029695ad02582a70eff08a6fd99d057e12e58e7d7b6b16cdfabc8ee2911;
global M20: Field = 0x2b90bba00fca0589f617e7dcbfe82e0df706ab640ceb247b791a93b74e36736d;
global M21: Field = 0x101071f0032379b697315876690f053d148d4e109f5fb065c8aacc55a0f89bfa;
global M22: Field = 0x19a3fc0a56702bf417ba7fee3802593fa644470307043f7773279cd71d25d5e0;

pub fn hash(input: [Field; 2]) -> Field {
    let mut state1 = ((input[0]) + 0x00f1445235f2148c5986587169fc1bcd887b08d4d00868df5696fff40956e864);
    let mut state2 = ((input[1]) + 0x08dff3487e8ac99e1f29a058d0fa80b930c728730b7ab36ce879f3890ecf73f5);
    let mut scratch0 = (state1 * state1);
    state1 = ((scratch0 * scratch0) * state1);
